<script>
// ============================================================
// SETUP
// ============================================================
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
const W = canvas.width;
const H = canvas.height;
const CX = W / 2;
const CY = H / 2;

// Neon palette
const COLORS = {
  bg: '#05070f',
  bgGlow: '#101a3a',
  branch: '#00e5ff',
  accent: '#d6ff00',
  synapse: '#ff2bd6',
  pulse: '#fff36a',
  accentUI: '#ffd400',
  scanline: 'rgba(0, 229, 255, 0.08)'
};

// State
let paused = false;
let branches = [];      // { points: [{x,y}], thickness, color, depth, tipX, tipY, growing }
let synapses = [];       // { x1,y1,x2,y2, phase }
let pulses = [];         // { synapseIdx, progress, speed, brightness }
let neurons = [];        // seed positions
let growthPhase = true;  // true while branches are still growing

// ============================================================
// GUI SETUP
// ============================================================
const params = {
  // Growth
  neuronCount: 4,
  growthSpeed: 3,
  maxDepth: 4,
  splitChance: 0.3,
  curvature: 0.4,
  maxLength: 120,

  // Synapses
  synapseThreshold: 40,
  synapseGlow: 1.0,

  // Pulses
  pulseSpeed: 1.5,
  pulseFrequency: 0.02,
  pulseBrightness: 1.0,

  // Visuals
  backgroundColor: COLORS.bg,
  branchColor: COLORS.branch,
  accentBranchColor: COLORS.accent,
  synapseColor: COLORS.synapse,
  pulseColor: COLORS.pulse,

  // Buttons
  regenerate: () => regenerateNetwork(),
  clearCanvas: () => {
    branches = []; synapses = []; pulses = []; neurons = []; growthPhase = true;
  },
  pauseResume: () => { paused = !paused; }
};

const gui = new dat.GUI({ width: 300 });
gui.add(params, 'neuronCount', 3, 6).step(1).name('Neuron Count');
gui.add(params, 'growthSpeed', 1, 10).step(0.5).name('Growth Speed');
gui.add(params, 'maxDepth', 2, 7).step(1).name('Max Depth');
gui.add(params, 'splitChance', 0, 1).step(0.05).name('Split Chance');
gui.add(params, 'curvature', 0.1, 1.0).step(0.05).name('Curvature');
gui.add(params, 'maxLength', 60, 250).step(10).name('Max Length');

gui.add(params, 'synapseThreshold', 15, 80).step(5).name('Synapse Threshold');
gui.add(params, 'synapseGlow', 0.2, 2.0).step(0.1).name('Synapse Glow');

gui.add(params, 'pulseSpeed', 0.5, 4.0).step(0.1).name('Pulse Speed');
gui.add(params, 'pulseFrequency', 0.005, 0.05).step(0.005).name('Pulse Freq');
gui.add(params, 'pulseBrightness', 0.3, 2.0).step(0.1).name('Pulse Brightness');

gui.addColor(params, 'backgroundColor').name('Background');
gui.addColor(params, 'branchColor').name('Branch Color');
gui.addColor(params, 'accentBranchColor').name('Accent Color');
gui.addColor(params, 'synapseColor').name('Synapse Color');
gui.addColor(params, 'pulseColor').name('Pulse Color');

gui.add(params, 'regenerate').name('Regenerate Network');
gui.add(params, 'clearCanvas').name('Clear Canvas');
gui.add(params, 'pauseResume').name('Pause / Resume');

// ============================================================
// NEURON GROWTH
// ============================================================
function generateNeurons() {
  neurons = [];
  const count = params.neuronCount;
  for (let i = 0; i < count; i++) {
    const angle = (Math.PI * 2 / count) * i + (Math.random() - 0.5) * 0.5;
    const dist = 30 + Math.random() * 40;
    neurons.push({
      x: CX + Math.cos(angle) * dist,
      y: CY + Math.sin(angle) * dist
    });
  }
}

function growBranchFrom(neuron, depth) {
  if (depth > params.maxDepth || branches.length > 600) return;

  const angle = Math.random() * Math.PI * 2;
  const startLen = 15 + Math.random() * 25;
  const thickness = Math.max(1, 3 - depth * 0.4 + (Math.random() - 0.5) * 1.5);
  const isAccent = Math.random() < 0.2;
  const color = isAccent ? params.accentBranchColor : params.branchColor;

  const branch = {
    points: [{ x: neuron.x, y: neuron.y }],
    thickness,
    color,
    depth,
    tipX: neuron.x,
    tipY: neuron.y,
    growing: true,
    angle,
    remainingLen: startLen
  };
  branches.push(branch);
}

function stepGrowth() {
  if (!growthPhase) return;
  let stillGrowing = false;
  const speed = params.growthSpeed;

  for (let b of branches) {
    if (!b.growing) continue;
    if (b.remainingLen <= 0) {
      b.growing = false;
      continue;
    }
    stillGrowing = true;

    const len = Math.min(speed, b.remainingLen);
    const curve = (Math.random() - 0.5) * params.curvature;
    b.angle += curve;

    const dx = Math.cos(b.angle) * len;
    const dy = Math.sin(b.angle) * len;

    const prev = b.points[b.points.length - 1];
    const next = { x: prev.x + dx, y: prev.y + dy };
    b.points.push(next);
    b.tipX = next.x;
    b.tipY = next.y;
    b.remainingLen -= len;

    // Side branch chance
    if (Math.random() < params.splitChance && b.depth < params.maxDepth && b.points.length < 8) {
      const sideAngle = b.angle + (Math.random() > 0.5 ? 1 : -1) * (0.5 + Math.random() * 0.8);
      const sideLen = 8 + Math.random() * 15;
      const sideBranch = {
        points: [{ x: next.x, y: next.y }],
        thickness: Math.max(1, b.thickness * 0.5),
        color: b.color,
        depth: b.depth + 1,
        tipX: next.x,
        tipY: next.y,
        growing: true,
        angle: sideAngle,
        remainingLen: sideLen
      };
      branches.push(sideBranch);
    }
  }

  if (!stillGrowing) growthPhase = false;
}

function regenerateNetwork() {
  branches = [];
  synapses = [];
  pulses = [];
  growthPhase = true;
  generateNeurons();
  for (const n of neurons) {
    growBranchFrom(n, 0);
  }
}

// ============================================================
// SYNAPSE DETECTION
// ============================================================
function detectSynapses() {
  const threshold = params.synapseThreshold;
  const newSynapses = [];

  for (let i = 0; i < branches.length; i++) {
    const b1 = branches[i];
    if (!b1.growing && b1.points.length < 2) continue;
    const t1 = b1.points[b1.points.length - 1];
    if (!t1) continue;

    for (let j = i + 1; j < branches.length; j++) {
      const b2 = branches[j];
      if (!b2.growing && b2.points.length < 2) continue;
      const t2 = b2.points[b2.points.length - 1];
      if (!t2) continue;

      const dx = t1.x - t2.x;
      const dy = t1.y - t2.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist < threshold) {
        // Check for duplicates
        let dup = false;
        for (const s of synapses) {
          if ((s.i === i && s.j === j) || (s.i === j && s.j === i)) { dup = true; break; }
        }
        if (!dup) {
          newSynapses.push({ i, j, phase: Math.random() * Math.PI * 2 });
        }
      }
    }
  }
  synapses.push(...newSynapses);
}

// ============================================================
// PULSE ANIMATION
// ============================================================
function spawnPulse() {
  if (synapses.length === 0 || Math.random() > params.pulseFrequency) return;
  const si = Math.floor(Math.random() * synapses.length);
  pulses.push({
    synapseIdx: si,
    progress: 0,
    direction: Math.random() > 0.5 ? 1 : -1,
    brightness: 0.5 + Math.random() * 0.5
  });
}

function stepPulses() {
  const s = params.pulseSpeed;
  for (let i = pulses.length - 1; i >= 0; i--) {
    pulses[i].progress += s * 0.01 * pulses[i].direction;
    if (Math.abs(pulses[i].progress) > 1) {
      pulses.splice(i, 1);
    }
  }
}

// ============================================================
// RENDERING
// ============================================================
function drawBackground() {
  ctx.fillStyle = params.backgroundColor;
  ctx.fillRect(0, 0, W, H);

  // Background glow circle
  const grad = ctx.createRadialGradient(CX, CY, 20, CX, CY, 350);
  grad.addColorStop(0, params.branchColor.replace(')', ', 0.05)').replace('#', ''));
  // Use hex to rgba manually
  const glowColor = params.branchColor;
  grad.addColorStop(0, 'rgba(0, 229, 255, 0.04)');
  grad.addColorStop(1, 'rgba(0, 0, 0, 0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);

  // Scanlines
  ctx.strokeStyle = COLORS.scanline;
  ctx.lineWidth = 1;
  for (let y = 0; y < H; y += 4) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(W, y);
    ctx.stroke();
  }
}

function drawVignette() {
  const grad = ctx.createRadialGradient(CX, CY, 200, CX, CY, 500);
  grad.addColorStop(0, 'rgba(0,0,0,0)');
  grad.addColorStop(1, 'rgba(0,0,0,0.6)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);
}

function drawBranch(branch) {
  if (branch.points.length < 2) return;
  ctx.save();
  ctx.strokeStyle = branch.color;
  ctx.lineWidth = branch.thickness;
  ctx.shadowColor = branch.color;
  ctx.shadowBlur = 8;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  ctx.beginPath();
  ctx.moveTo(branch.points[0].x, branch.points[0].y);
  for (let i = 1; i < branch.points.length; i++) {
    const p0 = branch.points[i - 1];
    const p1 = branch.points[i];
    const midX = (p0.x + p1.x) / 2;
    const midY = (p0.y + p1.y) / 2;
    ctx.quadraticCurveTo(p0.x, p0.y, midX, midY);
  }
  const last = branch.points[branch.points.length - 1];
  ctx.lineTo(last.x, last.y);
  ctx.stroke();
  ctx.restore();
}

function drawSynapses(time) {
  for (const s of synapses) {
    const b1 = branches[s.i];
    const b2 = branches[s.j];
    if (!b1 || !b2) continue;
    const t1 = b1.points[b1.points.length - 1] || b1.points[0];
    const t2 = b2.points[b2.points.length - 1] || b2.points[0];
    if (!t1 || !t2) continue;

    const pulse = 0.5 + 0.5 * Math.sin(time * 0.003 + s.phase);
    const glow = params.synapseGlow * pulse;

    ctx.save();
    ctx.strokeStyle = params.synapseColor;
    ctx.lineWidth = 1.5;
    ctx.shadowColor = params.synapseColor;
    ctx.shadowBlur = 12 * glow;
    ctx.globalAlpha = 0.4 + 0.4 * pulse;
    ctx.beginPath();
    ctx.moveTo(t1.x, t1.y);
    ctx.lineTo(t2.x, t2.y);
    ctx.stroke();

    // Center glow dot
    const mx = (t1.x + t2.x) / 2;
    const my = (t1.y + t2.y) / 2;
    const dotR = 2 + 2 * pulse;
    ctx.shadowBlur = 20 * glow;
    ctx.fillStyle = params.synapseColor;
    ctx.beginPath();
    ctx.arc(mx, my, dotR, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }
}

function drawPulses() {
  for (const p of pulses) {
    const s = synapses[p.synapseIdx];
    if (!s) continue;
    const b1 = branches[s.i];
    const b2 = branches[s.j];
    if (!b1 || !b2) continue;
    const t1 = b1.points[b1.points.length - 1] || b1.points[0];
    const t2 = b2.points[b2.points.length - 1] || b2.points[0];
    if (!t1 || !t2) continue;

    const prog = Math.abs(p.progress);
    const x = t1.x + (t2.x - t1.x) * prog;
    const y = t1.y + (t2.y - t1.y) * prog;
    const bright = p.brightness * params.pulseBrightness;

    ctx.save();
    ctx.shadowColor = params.pulseColor;
    ctx.shadowBlur = 15 * bright;
    ctx.fillStyle = params.pulseColor;
    ctx.globalAlpha = bright;
    ctx.beginPath();
    ctx.arc(x, y, 2.5 * bright, 0, Math.PI * 2);
    ctx.fill();

    // Trail
    const trailLen = 0.08;
    const tx = t1.x + (t2.x - t1.x) * Math.max(0, prog - trailLen);
    const ty = t1.y + (t2.y - t1.y) * Math.max(0, prog - trailLen);
    ctx.strokeStyle = params.pulseColor;
    ctx.lineWidth = 1.5;
    ctx.globalAlpha = bright * 0.6;
    ctx.beginPath();
    ctx.moveTo(tx, ty);
    ctx.lineTo(x, y);
    ctx.stroke();
    ctx.restore();
  }
}

function drawNeuronSeeds() {
  for (const n of neurons) {
    ctx.save();
    ctx.shadowColor = params.branchColor;
    ctx.shadowBlur = 20;
    ctx.fillStyle = params.branchColor;
    ctx.beginPath();
    ctx.arc(n.x, n.y, 4, 0, Math.PI * 2);
    ctx.fill();

    ctx.shadowColor = params.accentBranchColor;
    ctx.shadowBlur = 12;
    ctx.strokeStyle = params.accentBranchColor;
    ctx.lineWidth = 1.5;
    ctx.globalAlpha = 0.6 + 0.3 * Math.sin(Date.now() * 0.003);
    ctx.beginPath();
    ctx.arc(n.x, n.y, 7, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  }
}

// ============================================================
// ANIMATION LOOP
// ============================================================
let lastTime = 0;
let frameCount = 0;

function animate(time) {
  requestAnimationFrame(animate);

  if (paused) return;

  // Step growth
  if (growthPhase) {
    stepGrowth();
    if (frameCount % 3 === 0) detectSynapses();
  }

  // Spawn pulses
  spawnPulse();
  stepPulses();

  // Render
  drawBackground();
  drawVignette();

  for (const b of branches) drawBranch(b);
  drawSynapses(time);
  drawPulses();
  drawNeuronSeeds();

  frameCount++;
}

// ============================================================
// INIT
// ============================================================
generateNeurons();
for (const n of neurons) {
  growBranchFrom(n, 0);
}
requestAnimationFrame(animate);
</script>
</body>
</html>
